use MongoDB\Driver\ReadConcern;
use MongoDB\Driver\ReadPreference;

final class CommerceReports
{
    public function __construct(private readonly CommerceStore $s) {}
    public function report(Request $r,string $chain): array
    {
        $d=$r->validate(['from'=>'required|date_format:Y-m-d','to'=>'required|date_format:Y-m-d|after_or_equal:from','branch_id'=>'nullable|string|regex:/^[1-9][0-9]{0,18}$/']);$branch=$d['branch_id']??null;$u=$this->s->admin($r,$chain,$branch,$branch===null);if($branch)abort_unless($this->s->identity->assignments((string)$u->id,true)->contains(fn($a)=>$a['chain_id']===$chain&&($a['role_code']==='chain_owner'||($a['role_code']==='branch_manager'&&$a['branch_id']===$branch))),403);$from=new \DateTimeImmutable($d['from'].' 00:00:00',new \DateTimeZone('Asia/Ho_Chi_Minh'));$to=new \DateTimeImmutable($d['to'].' 00:00:00',new \DateTimeZone('Asia/Ho_Chi_Minh'));abort_unless($from->diff($to)->days<=366,422,'Mỗi lần xem tối đa 367 ngày.');$to=$to->modify('+1 day');$session=$this->s->identity->runtime->client->startSession();$session->startTransaction(['readConcern'=>new ReadConcern('snapshot'),'readPreference'=>new ReadPreference('primary')]);$db=$this->s->identity->runtime->database;$options=['session'=>$session];
        try{
            $filter=['chain_id'=>$chain];if($branch)$filter['branch_id']=$branch;$all=$db->selectCollection('shop_orders')->find($filter,$options+['limit'=>20001])->toArray();abort_unless(count($all)<=20000,422,'Cần bộ lọc hẹp hơn trước khi tổng hợp dữ liệu lớn.');$orders=[];$counts=[];$branches=[];$products=[];$gross=$credit=$paid=$refund=$remaining=$discount=$shipping=BigDecimal::zero();$invoiceCount=0;
            foreach($all as $o){$created=$o['created_at']->toDateTimeImmutable();$inPeriod=$created>=$from&&$created<$to;if($inPeriod)$counts[$o['status']]=($counts[$o['status']]??0)+1;if(!$o['invoice_id'])continue;$invoice=$db->selectCollection('invoices')->findOne(['_id'=>$o['invoice_id']],$options);abort_unless($invoice,409,'Đơn đã ghi sổ thiếu hóa đơn.');$issued=$invoice['issued_at']->toDateTimeImmutable();if($issued<$from||$issued>=$to)continue;$invoiceCount++;$sumIn=$sumOut=$sumPaid=$sumRefund=$sumCredit=BigDecimal::zero();foreach($db->selectCollection('shop_exchange_transfers')->find(['target_invoice_id'=>$o['invoice_id']],$options) as $t)$sumIn=$sumIn->plus((string)$t['amount']);foreach($db->selectCollection('shop_exchange_transfers')->find(['source_invoice_id'=>$o['invoice_id']],$options) as $t)$sumOut=$sumOut->plus((string)$t['amount']);foreach($db->selectCollection('payments')->find(['invoice_id'=>$o['invoice_id'],'status'=>'completed'],$options) as $p)$sumPaid=$sumPaid->plus((string)$p['amount']);foreach($db->selectCollection('debt_transactions')->find(['invoice_id'=>$o['invoice_id'],'transaction_type'=>['$in'=>['sale_return_credit','customer_refund']]],$options) as $entry)if($entry['transaction_type']==='sale_return_credit')$sumCredit=$sumCredit->plus((string)$entry['amount']);else $sumRefund=$sumRefund->plus((string)$entry['amount']);$total=BigDecimal::of((string)$invoice['total_amount']);abort_unless($total->isEqualTo($o['total']),409,'Hóa đơn khác tổng đơn đã ghi sổ.');$netPaid=$sumPaid->minus($sumRefund)->plus($sumIn)->minus($sumOut);$adjusted=$total->minus($sumCredit);abort_unless($netPaid->isGreaterThanOrEqualTo(0)&&$adjusted->isGreaterThanOrEqualTo(0),409,'Dữ liệu hoàn/credit không hợp lệ.');$left=BigDecimal::max(BigDecimal::zero(),$adjusted->minus($netPaid));$gross=$gross->plus($total);$credit=$credit->plus($sumCredit);$paid=$paid->plus($sumPaid);$refund=$refund->plus($sumRefund);$remaining=$remaining->plus($left);$discount=$discount->plus($o['discount']);$shipping=$shipping->plus($o['shipping_fee']);$bid=$o['branch_id'];$branches[$bid]??=['branch_id'=>$bid,'name'=>$o['branch_name'],'invoice_count'=>0,'invoice_total'=>'0.00','credit'=>'0.00','remaining'=>'0.00'];$branches[$bid]['invoice_count']++;foreach(['invoice_total'=>$total,'credit'=>$sumCredit,'remaining'=>$left] as $k=>$v)$branches[$bid][$k]=(string)BigDecimal::of($branches[$bid][$k])->plus($v)->toScale(2);
                foreach($o['items'] as $item){$pid=$item['product_id'];$products[$pid]??=['product_id'=>$pid,'name'=>$item['name'],'quantity'=>'0.000','returned_quantity'=>'0.000','sale_total'=>'0.00'];$products[$pid]['quantity']=(string)BigDecimal::of($products[$pid]['quantity'])->plus($item['quantity'])->toScale(3);$products[$pid]['sale_total']=(string)BigDecimal::of($products[$pid]['sale_total'])->plus($item['total'])->toScale(2);}foreach($db->selectCollection('shop_returns')->find(['order_id'=>$o['_id'],'status'=>'received'],$options) as $ret)foreach($ret['items'] as $item){$pid=$item['product_id'];abort_unless(isset($products[$pid]),409);$products[$pid]['returned_quantity']=(string)BigDecimal::of($products[$pid]['returned_quantity'])->plus($item['quantity'])->toScale(3);}$orders[]=['order_id'=>$o['_id'],'order_no'=>$o['order_no'],'invoice_id'=>$invoice['_id'],'branch_id'=>$bid,'issued_at'=>$invoice['issued_at'],'payment_method'=>$o['payment_method'],'status'=>$o['status'],'invoice_total'=>(string)$total->toScale(2),'return_credit'=>(string)$sumCredit->toScale(2),'paid'=>(string)$sumPaid->toScale(2),'refund'=>(string)$sumRefund->toScale(2),'exchange_received'=>(string)$sumIn->toScale(2),'exchange_transferred'=>(string)$sumOut->toScale(2),'remaining'=>(string)$left->toScale(2)];
            }
            $products=array_values($products);usort($products,fn($a,$b)=>BigDecimal::of($b['sale_total'])->compareTo($a['sale_total'])?:strcmp($a['product_id'],$b['product_id']));return CommerceStore::present(['from'=>$d['from'],'to'=>$d['to'],'timezone'=>'Asia/Ho_Chi_Minh','basis'=>'Trạng thái theo ngày tạo đơn; tiền theo ngày xuất hóa đơn. Thanh toán/hoàn/credit tính đến lúc xem, kể cả phát sinh sau kỳ. Không cộng doanh thu chưa xuất.','status_counts'=>$counts,'summary'=>['invoice_count'=>$invoiceCount,'invoice_total'=>(string)$gross->toScale(2),'discount'=>(string)$discount->toScale(2),'shipping'=>(string)$shipping->toScale(2),'return_credit'=>(string)$credit->toScale(2),'adjusted_invoice_total'=>(string)$gross->minus($credit)->toScale(2),'collected'=>(string)$paid->toScale(2),'refunded'=>(string)$refund->toScale(2),'net_collected'=>(string)$paid->minus($refund)->toScale(2),'remaining'=>(string)$remaining->toScale(2),'average_invoice'=>$invoiceCount?(string)$gross->dividedBy($invoiceCount,2,RoundingMode::HalfUp):'0.00'],'by_branch'=>array_values($branches),'products'=>$products,'orders'=>$orders]);
        }finally{$session->abortTransaction();$session->endSession();}
    }
}
